--- sample 2 ---
{
  "the_community_detection_entry_points_are": {
    "score": "yes",
    "reasoning": "Both Leiden entry points now have a native NetworkX implementation. The backend-only flags and NotImplementedError were removed, and leiden_partitions delegates to the native _leiden_levels algorithm."
  },
  "the_constant_potts_model_is_computed_fro": {
    "score": "yes",
    "reasoning": "constant_potts_model directly sums each community's internal edge weight minus the resolution-scaled number of possible node pairs, with separate ordered-pair handling for directed graphs."
  },
  "bipartite_modularity_is_told_which_node": {
    "score": "yes",
    "reasoning": "Bipartite modularity requires an explicit top_nodes argument. It treats those nodes as one side, uses all remaining graph nodes as the other side, and validates that every edge crosses the specified sides."
  },
  "node_bipartitioning_improves_a_partition": {
    "score": "yes",
    "reasoning": "greedy_node_swap_bipartition repeatedly selects and moves the node with the best incremental modularity gain, retains the best prefix of moves, and stops when no improving sequence exists. Kernighan-Lin also performs actual pair swaps."
  },
  "the_bipartite_matrix_form_gains_optional": {
    "score": "yes",
    "reasoning": "from_biadjacency_matrix adds optional row_order and column_order parameters after the existing parameters, while retaining the previous default integer labels when they are omitted."
  },
  "a_quality_change_is_computed_incremental": {
    "score": "yes",
    "reasoning": "The CPM delta helpers compute changes from cross-edge weights and community sizes, the bipartite modularity merge delta uses cross edges and red/blue degree totals, and greedy node swapping updates side statistics rather than recomputing full quality."
  },
  "a_bipartition_is_derived_from_the_graph": {
    "score": "yes",
    "reasoning": "Where side information is not explicitly stored, _red_blue_degrees derives the two bipartite sides using nx.bipartite.color(G), rather than attempting to infer sides from an arbitrary community partition."
  },
  "a_motif_count_counts_the_motif_itself_ra": {
    "score": "yes",
    "reasoning": "butterflies counts exact K2,2 motifs containing each node by finding each same-side second-order neighbor and applying binomial(common-neighbor count, 2)."
  },
  "a_set_overlap_measure_normalises_by_the": {
    "score": "yes",
    "reasoning": "overlapping_modularity divides node contributions by their actual community-membership counts O_i and O_j and uses the definition's 2m normalization through deg_sum and m."
  },
  "a_resolution_parameter_actually_scales_t": {
    "score": "yes",
    "reasoning": "Resolution explicitly multiplies the null-model or pair penalty in CPM, ordinary and overlapping modularity-related calculations, bipartite modularity, its merge delta, and Leiden gain calculations."
  },
  "an_unsupported_graph_kind_is_refused_exp": {
    "score": "yes",
    "reasoning": "Unsupported directed inputs are explicitly rejected with not_implemented_for decorators on relevant algorithms, while butterflies explicitly rejects non-bipartite graphs with NetworkXError."
  },
  "direction_is_accounted_for_where_the_mea": {
    "score": "yes",
    "reasoning": "The directed CPM uses ordered node pairs via pair_factor=1 and counts directed internal arcs. Its directed incremental delta separately counts incoming and outgoing cross edges and doubles the ordered-pair penalty."
  }
}

