{
  "the_community_detection_entry_points_are": {
    "score": "yes",
    "reasoning": "The Leiden entry points no longer use `implemented_by_nx=False` or raise `NotImplementedError`; they now execute native NetworkX implementations through `_leiden_levels` and its local moving, refinement, and aggregation helpers."
  },
  "the_constant_potts_model_is_computed_fro": {
    "score": "yes",
    "reasoning": "`constant_potts_model` directly sums each community's internal edge weight minus the resolution-scaled number of possible node pairs, with separate ordered-pair handling for directed graphs."
  },
  "bipartite_modularity_is_told_which_node": {
    "score": "yes",
    "reasoning": "Bipartite `modularity` requires an explicit `top_nodes` argument and validates that every edge crosses between that set and its complement; it does not infer the bipartite sides from the communities."
  },
  "node_bipartitioning_improves_a_partition": {
    "score": "yes",
    "reasoning": "`greedy_node_swap_bipartition` starts from the supplied or default split, computes modularity gains for moving nodes, applies the best sequence of moves, rolls back moves after the best point, and iterates while improvement exists."
  },
  "the_bipartite_matrix_form_gains_optional": {
    "score": "yes",
    "reasoning": "`from_biadjacency_matrix` adds optional `row_order` and `column_order` parameters after the existing arguments, while preserving the prior default integer labels and old calling convention."
  },
  "a_quality_change_is_computed_incremental": {
    "score": "yes",
    "reasoning": "The CPM delta helpers and `_bipartite_modularity_merge_delta` calculate changes from cross-community edge weights, community sizes, and degree totals. The greedy node-swap routine likewise maintains side degrees and neighbor-side weights instead of recomputing modularity."
  },
  "a_bipartition_is_derived_from_the_graph": {
    "score": "yes",
    "reasoning": "Bipartite-side information comes from the explicit `top_nodes` set, node `bipartite` attributes, or a two-coloring of the graph, with the other side formed from the graph complement; it is not derived from an arbitrary community partition."
  },
  "a_motif_count_counts_the_motif_itself_ra": {
    "score": "yes",
    "reasoning": "`butterflies` exactly counts K2,2 motifs containing each node by finding each second-order same-side node and applying `C(common_neighbors, 2)`, which corresponds directly to the butterfly definition."
  },
  "a_set_overlap_measure_normalises_by_the": {
    "score": "yes",
    "reasoning": "`overlapping_modularity` computes each node's membership count `O_i` and divides edge and degree contributions by the relevant membership counts, while using the specified `2m`-equivalent degree-sum normalization."
  },
  "a_resolution_parameter_actually_scales_t": {
    "score": "yes",
    "reasoning": "Resolution explicitly multiplies the null-model or pair penalty in CPM, bipartite modularity, overlapping modularity, quality-delta helpers, and the Leiden gain parameter `gamma`."
  },
  "an_unsupported_graph_kind_is_refused_exp": {
    "score": "yes",
    "reasoning": "Algorithms that do not support directed graphs use `@not_implemented_for(\"directed\")`, and `butterflies` explicitly raises `NetworkXError` for a non-bipartite graph rather than silently processing it as bipartite."
  },
  "direction_is_accounted_for_where_the_mea": {
    "score": "yes",
    "reasoning": "Directed CPM uses ordered node pairs via a pair factor of 1, and its directed delta includes both outgoing and incoming cross-community edge weights with the corresponding doubled pair penalty."
  }
}
